# Generated from tools/data/rulebooks/axel_pong.json; run tools/compile-rulebooks.rb.
module GameRoomGames
  class AxelPong
    module GeneratedRulebook
      private

      def generated_rule_sections
        [
          rule_section(:origin, GameRoomRules.translate("About this adaptation"),
            GameRoomRules.translate("Axel Pong is not an original project by papierek. The game was originally called Dragon-Pong, was later improved by Axel and balteam, and has now been ported to ELTEN with their permission.")),
          rule_section(:court, GameRoomRules.translate("Follow the ball by sound"),
            GameRoomRules.translate("Axel Pong is an audio paddle game for two players, or four players in doubles. Move your paddle along your end of the court and return the ball before it passes you. You score one point when your opponent misses. You can play with other people or add bots to the table. Headphones make it much easier to hear where the ball is."),
            GameRoomRules.translate("Each player hears the court from their own end. A ball to your left sounds on the left; a ball to your right sounds on the right. It grows louder as it approaches you. A side-wall bounce has a higher pitch near your end and a lower pitch near the opponent. Paddle steps also have a pitch cue for position. There is no need to announce every movement: use C when you want to check your paddle's position.")),
          rule_section(:rally, GameRoomRules.translate("Serving and returning"),
            GameRoomRules.translate("Keep focus on the Pong playfield. Hold Left or Right to move, and press Up or Space to serve or hit. To serve diagonally, hold a direction while serving. A return is possible only when the ball is approaching your end and your paddle is close enough to it. A centred hit goes straight; an off-centre hit sends the ball diagonally. Hits speed up the ball, while lateral motion gradually weakens and loses more speed at a wall."),
            GameRoomRules.translate("In Single, the first server is chosen at the start of a human match; against a bot, the human starts. Service changes after every two completed points. After a point there is a three-second break for the goal recording, followed by the score and a further 2.7-second serve delay. You can reposition your paddle during this pause, but serving requires a new press after it ends."),
            GameRoomRules.translate("When creating the table, choose 7, 11 or 21 points to win, or select Custom number. With Custom number selected, Tab takes you to an edit field where you can enter a whole number from 2 to 999. In both Single and Doubles, reaching the target is not enough: you also need a lead of at least two points. At 10\u201310 in an 11-point match, 11\u201310 does not end the match; 12\u201310 does. The last choice, Unlimited, keeps counting points without declaring a winner or ending the match because of the score. Play continues until the table is closed or its owner ends the match with Ctrl+Q."),
            GameRoomRules.translate("Automatic return is a personal setting, off by default. When enabled, your paddle returns a reachable ball automatically near your end. You still position the paddle and serve yourself. Open Pong settings with Ctrl+P to change it; your opponent chooses independently."),
            GameRoomRules.translate("The first serve becomes available once the players are connected and ready, without an extra countdown. In a human-only match, you hear the variant, difficulty and target, then who serves. The break after subsequent points remains as described above.")),
          rule_section(:doubles, GameRoomRules.translate("Doubles"),
            GameRoomRules.translate("Choose Single or Doubles immediately after Game mode when creating the table. Doubles requires four players. Before starting, the table master assigns two players to each team in the standard team selection window. Each player has their own paddle and can reposition at any time. Partners must return alternately: if A serves to C, the rally continues C, B, D, A, C. Only the designated player can return, including automatic returns and shield returns. Each step is positioned at the paddle of the player who moved."),
            GameRoomRules.translate("The first player in each team uses a different footstep recording, while their partner keeps the standard footsteps. For teams A and B against C and D, A and C use the new sound; B and D keep the usual sound. Footstep pitch still indicates paddle position, without an extra pitch shift for either partner. Serves and returns by A and C are pitched four semitones lower than those by B and D. Everyone hears the same distinction, including spectators after changing perspective. Simultaneous paddle sounds do not cut each other off."),
            GameRoomRules.translate("The starting team is chosen once for the match. Each service block lasts two points. For teams A and B against C and D, the first cycle is A to C, D to B, B to D, C to A. The next cycle is A to D, C to B, B to C, D to A; then these cycles repeat. If the other team starts, exchange the teams' roles. Within every rally, the order is server, receiver, server's partner, receiver's partner, repeated until the point ends. Both partners share their team's points and victory."),
            GameRoomRules.translate("At the beginning of each two-point service block, the game announces who will serve against whom. After the spoken announcement, there is the same 2.7-second serve delay as in Single. The second serve uses the normal Single delay without repeating the announcement. You can move your paddle during the break, but serving requires a fresh press when the break ends. S reads Team A and Team B, both partners' names and the scores, separated by punctuation. T reads the server, receiver and connection status; C still reads your own paddle position.")),
          rule_section(:background, GameRoomRules.translate("Leaving the playfield"),
            GameRoomRules.translate("Opening a menu, help, Messages or another ELTEN window does not pause the match. The ball, bots, score and table chat continue to update. Keys used in that other window do not move your paddle or serve when you return. To defend manually, return to the playfield. The General category of Power Games settings controls speech outside the table window.")),
          rule_section(:mouse, GameRoomRules.translate("Moving with the mouse"),
            GameRoomRules.translate("On Windows, mouse control is always available in the Pong playfield; you do not need to enable it. Move the mouse mainly left or right to move your paddle in steps; a large sweep does not jump across the court. Click the left mouse button to serve or return the ball. Holding it can also return a reachable ball just before it passes your goal, but it does not automatically serve after the pause between points. Up, Space and the arrow keys still work. As in the original audio mode, a click hits before the mouse movement from the same frame is applied."),
            GameRoomRules.translate("Mouse movement works only while the Pong playfield and the ELTEN window are active. The pointer is kept near the centre of that window so the screen edge does not stop you. Chat, settings, help, another application or a lost connection suspends mouse control. Returning to play discards movement made elsewhere. This option adds no graphics and changes no Windows mouse settings. There is no mouse on/off switch.")),
          rule_section(:arcade, GameRoomRules.translate("Classic and Arcade"),
            GameRoomRules.translate("Choose Classic or Arcade in the Game mode list when creating the table. Classic is the default and follows the normal rules above. In Arcade, every paddle return has two independent chances of 7 percent: a shield for the player who returned the ball (both partners in Doubles) and an invisible ball. Both may happen on the same hit. A serve alone does not trigger these effects."),
            GameRoomRules.translate("A shield protects the whole goal for ten seconds of play. It returns a missed ball straight ahead without being used up. Winning another shield resets its time to ten seconds instead of adding to the remaining time; in Doubles, either partner resets it for both. An invisible ball is silent until a paddle returns it or a goal is scored. A shield bounce does not reveal it. Activation and shield expiry have distinct sounds; E reports the current effects. The remaining shield time is preserved between points and does not run down while waiting for a serve.")),
          rule_section(:difficulty, GameRoomRules.translate("Speed and opponents"),
            GameRoomRules.translate("Difficulty and ball speed has six levels: Easy, Normal, Hard, Insane, Impossible and Nightmare. Higher settings start with a faster ball. Against a bot, they also change reaction time, movement, aim and the chance of an error. The bot tracks the visible ball with limited precision and does not track an invisible ball. It may still return an invisible ball if its paddle happens to be in the right place.")),
          rule_section(:personal, GameRoomRules.translate("Your Pong settings"),
            GameRoomRules.translate("Ctrl+P and the Pong settings item in the table menu open your local Pong settings. Besides automatic return, you can adjust your paddle movement, the opponent's movement and the recorded announcer separately. Each volume ranges from 0 to 200 percent; 100 percent keeps the original balance, and 0 mutes that group. Power Games's overall volume still applies. Save keeps these values for your future matches on this computer; Cancel leaves them unchanged. They are not table rules and do not change the opponent's settings. The match continues while this panel is open, but its controls do not move your paddle.")),
          rule_section(:echo, GameRoomRules.translate("Finding the sides by sound"),
            GameRoomRules.translate("Shift+E changes side-wall cues between off, noise and tones. These are additional local sounds that help you judge your paddle's distance from the left and right edges. The nearer an edge is, the louder its cue. This setting does not move your paddle or change what your opponent hears. Power Games's sound-volume and mute controls still apply.")),
          rule_section(:hurry, GameRoomRules.translate("An opponent who does not serve"),
            GameRoomRules.translate("When playing another person, Ctrl+W warns the opponent to serve within ten seconds. It is available only after the normal break, while it is their serve and the ball has not been served yet. A valid serve cancels the warning; otherwise you receive a point. Repeated presses do not extend the deadline, and a new warning cannot be sent for fifteen seconds. Observers cannot issue warnings. A broken connection does not count as a late serve.")),
          rule_section(:connection, GameRoomRules.translate("When the connection is interrupted"),
            GameRoomRules.translate("The table and score use Power Games's normal session; movement uses Communications. During a human match, each player calculates their own flight and return locally. Lost or delayed paddle-position updates alone do not stop the ball. Serves, returns and misses travel separately in order. An actual connection failure pauses the rally; a replacement connection restarts the unfinished point with the confirmed score unchanged. Observers may listen but cannot control a paddle. Unfinished matches cannot currently be saved.")),
          rule_section(:watching, GameRoomRules.translate("Watching a match"),
            GameRoomRules.translate("C reads the name and paddle position of the player you are watching. S, T and E also work for observers: check the score, server and active effects without controlling the game. At the end of the match, you hear victory or defeat for the selected player or their team."),
            GameRoomRules.translate("As an observer, use the number keys in the Pong playfield to choose a player's perspective: 1 selects the first player, 2 the second, and in Doubles 3 the third and 4 the fourth. The numbers follow the player order in the match, not the teams. The game confirms the player's name. This changes only your listening perspective and the order of the spoken score after a point; it does not let you move any paddle. The choice stays in place between points. The keys do not select a perspective while you are typing in chat or reading history.")),
          rule_section(:controls, GameRoomRules.translate("Game keyboard shortcuts"),
            GameRoomRules.translate("Left arrow: move the paddle left."),
            GameRoomRules.translate("Right arrow: move the paddle right."),
            GameRoomRules.translate("Up arrow: serve or return the ball."),
            GameRoomRules.translate("Space: serve or return the ball."),
            GameRoomRules.translate("Ctrl+P: open your Pong settings."),
            GameRoomRules.translate("S: read scores."),
            GameRoomRules.translate("T: read the server and connection status."),
            GameRoomRules.translate("C: read your paddle position, or the observed player's position when watching."),
            GameRoomRules.translate("E: read active shields and invisible ball."),
            GameRoomRules.translate("Shift+E: change side-wall cues."),
            GameRoomRules.translate("1: as an observer, listen from the first player's perspective."),
            GameRoomRules.translate("2: as an observer, listen from the second player's perspective."),
            GameRoomRules.translate("3: as an observer in Doubles, listen from the third player's perspective."),
            GameRoomRules.translate("4: as an observer in Doubles, listen from the fourth player's perspective."),
            GameRoomRules.translate("Ctrl+W: hurry the opponent before a serve."))
        ]
      end

      def localized_rule_sections
        case GameRoomLocalization.primary_language
        when "cs"
          [
            rule_section(:goal, "C\u00EDl hry a zvuk m\u00ED\u010De",
              "V Axel Pongu p\u00E1lkou br\u00E1n\u00ED\u0161 svou branku a sna\u017E\u00ED\u0161 se odrazit m\u00ED\u010D mimo dosah soupe\u0159e. Kdy\u017E m\u00ED\u010D projde do tv\u00E9 branky, soupe\u0159 z\u00EDsk\u00E1 bod. Dvouhru hraj\u00ED dva hr\u00E1\u010Di; soupe\u0159em m\u016F\u017Ee b\u00FDt i bot.",
              "M\u00ED\u010D sly\u0161\u00ED\u0161 vlevo nebo vpravo podle jeho polohy v\u016F\u010Di sv\u00E9 p\u00E1lce. \u010C\u00EDm je bl\u00ED\u017E, t\u00EDm je hlasit\u011Bj\u0161\u00ED. Oba sign\u00E1ly se sn\u00E1z sleduj\u00ED ve sluch\u00E1tk\u00E1ch."),
            rule_section(:rally, "Pohyb p\u00E1lky a \u00FAdery",
              "P\u00E1lku posouv\u00E1\u0161 \u0161ipkami vlevo a vpravo. Pro del\u0161\u00ED pohyb kl\u00E1vesu podr\u017E.",
              "U bo\u010Dn\u00EDch st\u011Bn je zvuk pohybu p\u00E1lky hlubok\u00FD. Sm\u011Brem ke st\u0159edu se zvy\u0161uje a po jeho p\u0159ejet\u00ED zase kles\u00E1. Polohu p\u00E1lky p\u0159e\u010Dte C.",
              "Pod\u00E1n\u00ED provede\u0161 \u0161ipkou nahoru nebo mezern\u00EDkem. M\u00ED\u010D vylet\u00ED z m\u00EDsta, kde m\u00E1\u0161 p\u00E1lku. Pokud chce\u0161 podat \u0161ikmo, dr\u017E p\u0159i pod\u00E1n\u00ED \u0161ipku vlevo \u010Di vpravo.",
              "Po soupe\u0159ov\u011B \u00FAderu postav p\u00E1lku do cesty m\u00ED\u010Di. A\u017E se p\u0159ibl\u00ED\u017E\u00ED na jej\u00ED dosah, odraz ho \u0161ipkou nahoru nebo mezern\u00EDkem. Samotn\u00E9 spr\u00E1vn\u00E9 postaven\u00ED nesta\u010D\u00ED, \u00FAder mus\u00ED p\u0159ij\u00EDt v dosahu m\u00ED\u010De.",
              "Sm\u011Br odrazu z\u00E1vis\u00ED na zasa\u017Een\u00E9 \u010D\u00E1sti p\u00E1lky:",
              "- St\u0159ed vrac\u00ED m\u00ED\u010D p\u0159\u00EDmo.",
              "- Lev\u00E1 \u010D\u00E1st ho odraz\u00ED \u0161ikmo doleva.",
              "- Prav\u00E1 \u010D\u00E1st ho odraz\u00ED \u0161ikmo doprava.",
              "Tak m\u016F\u017Ee\u0161 m\u00ED\u0159it do m\u00EDsta, kter\u00E9 soupe\u0159 nehl\u00EDd\u00E1. S ka\u017Ed\u00FDm odrazem m\u00ED\u010D zrychluje.",
              "M\u00ED\u010D se odr\u00E1\u017E\u00ED i od bo\u010Dn\u00EDch st\u011Bn. Zvuk tohoto odrazu je t\u00EDm vy\u0161\u0161\u00ED, \u010D\u00EDm bl\u00ED\u017E k tob\u011B nastal; u soupe\u0159ovy branky je nejhlub\u0161\u00ED."),
            rule_section(:points, "Pod\u00E1n\u00ED a sk\u00F3re",
              "Proti botovi pod\u00E1v\u00E1\u0161 jako prvn\u00ED. P\u0159i h\u0159e dvou lid\u00ED usly\u0161\u00ED\u0161, kdo za\u010D\u00EDn\u00E1. D\u00E1l se pod\u00E1n\u00ED st\u0159\u00EDd\u00E1 po dvou bodech. Pod\u00E1vaj\u00EDc\u00EDho p\u0159ipomene T.",
              "Vyhraje\u0161 s nejm\u00E9n\u011B 11 body a n\u00E1skokem dvou. Za stavu 11:10 se je\u0161t\u011B hraje, 12:10 u\u017E z\u00E1pas ukon\u010D\u00ED. Sk\u00F3re p\u0159e\u010Dte S.",
              "Ve h\u0159e bez bot\u016F lze v\u00E1haj\u00EDc\u00EDho soupe\u0159e vyzvat k pod\u00E1n\u00ED pomoc\u00ED Ctrl+W. M\u00E1 pak deset sekund na zah\u00E1jen\u00ED v\u00FDm\u011Bny, jinak z\u00EDsk\u00E1\u0161 bod. Dal\u0161\u00ED v\u00FDzvu m\u016F\u017Ee\u0161 poslat po patn\u00E1cti sekund\u00E1ch."),
            rule_section(:doubles, "\u010Cty\u0159hra",
              "V nastaven\u00ED stolu lze zvolit \u010Dty\u0159hru se dv\u011Bma dvou\u010Dlenn\u00FDmi t\u00FDmy. S partnerem br\u00E1n\u00EDte spole\u010Dnou branku a z\u00EDsk\u00E1v\u00E1te spole\u010Dn\u00E9 body, ka\u017Ed\u00FD ale ovl\u00E1d\u00E1 vlastn\u00ED p\u00E1lku.",
              "V \u00FAderech se mus\u00EDte st\u0159\u00EDdat. Kdy\u017E pod\u00E1v\u00E1\u0161 ty, n\u00E1sleduje toto po\u0159ad\u00ED:",
              "- Pod\u00E1n\u00ED p\u0159ijme jeden soupe\u0159.",
              "- Vr\u00E1cen\u00FD m\u00ED\u010D odraz\u00ED tv\u016Fj partner.",
              "- Potom hraje druh\u00FD soupe\u0159.",
              "- Dal\u0161\u00ED m\u00ED\u010D je op\u011Bt tv\u016Fj.",
              "Po\u0159ad\u00ED se opakuje a\u017E do konce v\u00FDm\u011Bny. Za partnera hr\u00E1t nesm\u00ED\u0161, ani kdy\u017E jsi k m\u00ED\u010Di bl\u00ED\u017E.",
              "Prvn\u00ED pod\u00E1vaj\u00EDc\u00ED t\u00FDm se losuje. Po dvou bodech se zm\u011Bn\u00ED pod\u00E1vaj\u00EDc\u00ED i p\u0159ij\u00EDmaj\u00EDc\u00ED. Hra ohl\u00E1s\u00ED, kdo pod\u00E1v\u00E1 na koho; p\u0159ipomene to i T. Kl\u00E1vesa S p\u0159e\u010Dte slo\u017Een\u00ED t\u00FDm\u016F a sk\u00F3re.",
              "P\u00E1lky partner\u016F maj\u00ED odli\u0161n\u00E9 zvuky pohybu. Prvn\u00ED hr\u00E1\u010D ka\u017Ed\u00E9ho t\u00FDmu m\u00E1 nav\u00EDc hlub\u0161\u00ED zvuk pod\u00E1n\u00ED a \u00FAderu ne\u017E druh\u00FD."),
            rule_section(:arcade, "Re\u017Eim Arcade",
              "B\u011B\u017En\u00FD re\u017Eim se jmenuje Classic. P\u0159ed hrou jej lze nahradit re\u017Eimem Arcade s dopl\u0148kov\u00FDmi efekty. Ka\u017Ed\u00FD odraz p\u00E1lkou m\u00E1 samostatn\u011B 7% \u0161anci na \u0161t\u00EDt a 7% na neviditeln\u00FD m\u00ED\u010D; mohou nastat i oba. P\u0159i pod\u00E1n\u00ED se efekty nelosuj\u00ED.",
              "- \u0160t\u00EDt chr\u00E1n\u00ED celou tvou hranu po deset sekund hry. Kdy\u017E m\u00ED\u010D pust\u00ED\u0161, vr\u00E1t\u00ED ho p\u0159\u00EDmo a ochrana pokra\u010Duje. Dal\u0161\u00ED \u0161t\u00EDt obnov\u00ED dobu ochrany. Ve \u010Dty\u0159h\u0159e kryje oba partnery. P\u0159i \u010Dek\u00E1n\u00ED na pod\u00E1n\u00ED \u010Das \u0161t\u00EDtu neub\u00FDv\u00E1 a zb\u00FDvaj\u00EDc\u00ED ochrana p\u0159ejde do dal\u0161\u00EDho bodu.",
              "- Neviditeln\u00FD m\u00ED\u010D nen\u00ED sly\u0161et. Jeho dr\u00E1hu mus\u00ED\u0161 odhadnout a zkusit p\u00E1lku v\u010Das postavit. Odraz p\u00E1lkou zvuk obnov\u00ED, odraz \u0161t\u00EDtem ne. Neviditelnost skon\u010D\u00ED tak\u00E9 koncem bodu.",
              "Aktivn\u00ED efekty p\u0159e\u010Dte E."),
            rule_section(:options, "Rychlost a d\u00E9lka z\u00E1pasu",
              "Obt\u00ED\u017Enost vyb\u00EDr\u00E1\u0161 p\u0159ed hrou v nastaven\u00ED stolu; v\u00FDchoz\u00ED je Norm\u00E1ln\u00ED. Na snaz\u0161\u00EDch \u00FArovn\u00EDch je m\u00ED\u010D pomalej\u0161\u00ED, na t\u011B\u017E\u0161\u00EDch rychlej\u0161\u00ED. S obt\u00ED\u017Enost\u00ED roste tak\u00E9 s\u00EDla bota.",
              "M\u00EDsto 11 bod\u016F lze zvolit 7 nebo 21, p\u0159\u00EDpadn\u011B zadat vlastn\u00ED c\u00EDl. Po\u0159\u00E1d pot\u0159ebuje\u0161 n\u00E1skok dvou bod\u016F.",
              "Nekone\u010Dn\u00E1 hra sk\u00F3re po\u010D\u00EDt\u00E1, ale \u017E\u00E1dn\u00FD v\u00FDsledek ji neukon\u010D\u00ED. Takov\u00FD z\u00E1pas ukon\u010Duje hostitel pomoc\u00ED Ctrl+Q."),
            rule_section(:personal, "My\u0161, automatick\u00E9 \u00FAdery a zvuky",
              "Na hern\u00EDm poli Ponga funguje i my\u0161 nebo touchpad. Pohybem vlevo a vpravo posouv\u00E1\u0161 p\u00E1lku, lev\u00FDm tla\u010D\u00EDtkem pod\u00E1v\u00E1\u0161 a odpaluje\u0161.",
              "Osobn\u00ED nastaven\u00ED otev\u0159e\u0161 pomoc\u00ED Ctrl+P:",
              "- Automatick\u00E9 odr\u00E1\u017Een\u00ED ude\u0159\u00ED samo, kdy\u017E je m\u00ED\u010D v dosahu p\u00E1lky. Pohyb a pod\u00E1n\u00ED z\u016Fst\u00E1vaj\u00ED na tob\u011B. Ve v\u00FDchoz\u00EDm nastaven\u00ED je tato pomoc vypnut\u00E1.",
              "- Hlasitost vlastn\u00ED p\u00E1lky zes\u00EDl\u00ED nebo zti\u0161\u00ED zvuk tv\u00E9ho pohybu.",
              "- Hlasitost soupe\u0159ovy p\u00E1lky uprav\u00ED zvuk jeho pohybu.",
              "- Hlasitost koment\u00E1tora uprav\u00ED hlasitost mluven\u00FDch hern\u00EDch ozn\u00E1men\u00ED.",
              "Pomoc\u00ED Shift+E p\u0159ep\u00EDn\u00E1\u0161 zvuky bo\u010Dn\u00EDch hran mezi \u0161umem, t\u00F3ny a vypnut\u00EDm. \u010C\u00EDm bl\u00ED\u017E k hran\u011B p\u00E1lka stoj\u00ED, t\u00EDm hlasit\u011Bji dan\u00FD sign\u00E1l zn\u00ED."),
            rule_section(:credits, "P\u016Fvod hry",
              "Axel Pong nen\u00ED p\u016Fvodn\u00ED hra od papierka. Vznikl jako Dragon-Pong a n\u00E1sledn\u011B jej vylep\u0161ili Axel a balteam. Do ELTENu byl p\u0159enesen s jejich souhlasem."),
            rule_section(:controls, "Kl\u00E1vesov\u00E9 zkratky",
              "\u0160ipka vlevo: posunout p\u00E1lku vlevo.",
              "\u0160ipka vpravo: posunout p\u00E1lku vpravo.",
              "\u0160ipka nahoru: podat nebo odrazit m\u00ED\u010D.",
              "Mezern\u00EDk: podat nebo odrazit m\u00ED\u010D.",
              "Lev\u00E9 tla\u010D\u00EDtko my\u0161i: podat nebo odrazit m\u00ED\u010D.",
              "C: p\u0159e\u010D\u00EDst polohu vlastn\u00ED nebo sledovan\u00E9 p\u00E1lky.",
              "S: p\u0159e\u010D\u00EDst sk\u00F3re a ve \u010Dty\u0159h\u0159e tak\u00E9 t\u00FDmy.",
              "T: ozn\u00E1mit pod\u00E1vaj\u00EDc\u00EDho a stav p\u0159ipojen\u00ED, ve \u010Dty\u0159h\u0159e i p\u0159ij\u00EDmaj\u00EDc\u00EDho.",
              "Ctrl+W: vyzvat soupe\u0159e k pod\u00E1n\u00ED.",
              "E: p\u0159e\u010D\u00EDst aktivn\u00ED efekty Arcade.",
              "Shift+E: p\u0159epnout zvuky bo\u010Dn\u00EDch hran.",
              "Ctrl+P: otev\u0159\u00EDt osobn\u00ED nastaven\u00ED Ponga.",
              "1: p\u0159i sledov\u00E1n\u00ED poslouchat z pohledu prvn\u00EDho hr\u00E1\u010De.",
              "2: p\u0159i sledov\u00E1n\u00ED poslouchat z pohledu druh\u00E9ho hr\u00E1\u010De.",
              "3: p\u0159i sledov\u00E1n\u00ED \u010Dty\u0159hry poslouchat z pohledu t\u0159et\u00EDho hr\u00E1\u010De.",
              "4: p\u0159i sledov\u00E1n\u00ED \u010Dty\u0159hry poslouchat z pohledu \u010Dtvrt\u00E9ho hr\u00E1\u010De.")
          ]
        when "en"
          [
            rule_section(:goal, "The game",
              "In Axel Pong, move your paddle to protect your goal and hit the ball where your opponent cannot reach it. A ball in your goal gives them a point. Singles is played by two people, or by one person against a bot.",
              "The ball sounds to the left or right according to its position relative to your paddle, and gets louder as it approaches. Headphones make both clues easier to follow."),
            rule_section(:rally, "Moving and hitting",
              "Move your paddle with Left and Right arrow. Hold a key to keep moving.",
              "Your movement sound is low near either side wall and rises as you approach the middle of the table. After you cross the middle, it falls again. Press C to hear your paddle's position.",
              "When it is your serve, press Up arrow or Space. The ball leaves from your paddle's position. Hold Left or Right arrow as you serve to send it at an angle.",
              "When the opponent returns the ball, move into its path and press Up arrow or Space once it is close enough to hit. Being in the right place is only half the task: the ball must also be within your paddle's reach when you hit.",
              "The part of the paddle that meets the ball determines its direction:",
              "- The centre sends it straight ahead.",
              "- The left side sends it diagonally left.",
              "- The right side sends it diagonally right.",
              "Use these angles to aim away from your opponent. The ball speeds up with each hit.",
              "The ball can also bounce off the side walls. A wall bounce sounds higher when it happens closer to your goal, and lowest near your opponent's goal."),
            rule_section(:points, "Service and scoring",
              "Against a bot, you serve first. In a match between people, the game announces the first server. Service changes sides after every two points. Press T to check who serves next.",
              "The usual target is 11 points, with a two-point lead needed to win. Play continues at 11\u201310, but 12\u201310 wins the match. Press S for the current score.",
              "In a match without bots, Ctrl+W hurries an opponent who is delaying their serve. They have ten seconds to serve or you get a point. You can hurry them again after fifteen seconds."),
            rule_section(:doubles, "Doubles",
              "Choose doubles in the table settings to play in two teams of two. You and your partner defend the same goal and share a score, but each of you controls a separate paddle.",
              "Partners take turns hitting. If you serve, the rally follows this order:",
              "1. One opponent receives your serve.",
              "2. Your partner takes the return.",
              "3. The other opponent hits next.",
              "4. The next ball is yours.",
              "Repeat that order until the point ends. You cannot take your partner's ball, even if you are closer to it.",
              "The opening serving team is chosen at random. The server and receiver change every two points. Their names are announced, and T repeats them. S reads the teams and score.",
              "The two partners have different movement sounds. The first player on each team also has a lower-pitched serve and hit sound than the second."),
            rule_section(:arcade, "Arcade mode",
              "Classic is the normal game. Arcade adds two possible effects to paddle hits: each hit has a 7% chance of a shield and a separate 7% chance of an invisible ball, so both can occur together. Serving does not trigger them.",
              "- A shield protects your whole end for ten seconds of play. If you miss, it sends the ball straight back and remains active. Another shield renews the protection. In doubles it covers both partners. Waiting for a serve does not use up shield time, and any time left carries over to the next point.",
              "- An invisible ball is silent. You must judge where it is going and put your paddle in its path. A paddle hit makes it audible again; a shield bounce does not. The effect also ends when the point is over.",
              "Press E to check which effects are active."),
            rule_section(:options, "Speed and match length",
              "Set the difficulty before play. Normal is the default; easier levels start with a slower ball, and harder levels with a faster one. Bots also play better at higher difficulties.",
              "You can choose a target of 7 or 21 points instead of 11, or enter your own under Custom. A two-point lead is still required.",
              "Infinite keeps counting points without ending the match at a target score. The table host can end it with Ctrl+Q."),
            rule_section(:personal, "Mouse and sound settings",
              "You can also play with a mouse or touchpad. Move it left and right to position the paddle; the left mouse button serves and hits. Mouse control is available immediately while the Pong playing field is focused.",
              "Press Ctrl+P for your personal Pong settings:",
              "- Automatic hitting makes your paddle return a ball within reach. You still need to move it and serve. It is off by default.",
              "- Your paddle volume adjusts your movement sound.",
              "- Opponent paddle volume adjusts the other player's movement sound.",
              "- Announcer volume adjusts the game's recorded announcements.",
              "Shift+E cycles the side-wall cues through noise, tones and off. Each wall's cue becomes louder as your paddle approaches it."),
            rule_section(:credits, "Origins",
              "Axel Pong is not an original game by papierek. It began as Dragon-Pong and was later improved by Axel and balteam. It was ported to ELTEN with their permission."),
            rule_section(:controls, "Keyboard shortcuts",
              "Left arrow: move the paddle left.",
              "Right arrow: move the paddle right.",
              "Up arrow: serve or hit.",
              "Space: serve or hit.",
              "Left mouse button: serve or hit.",
              "C: read your paddle position, or the watched player's position.",
              "S: read the score and, in doubles, the teams.",
              "T: read the server and connection status; in doubles, also the receiver.",
              "Ctrl+W: hurry the opponent before a serve.",
              "E: read active Arcade effects.",
              "Shift+E: change side-wall sounds.",
              "Ctrl+P: open Pong settings.",
              "1: as a spectator, listen from the first player's perspective.",
              "2: as a spectator, listen from the second player's perspective.",
              "3: in doubles, listen from the third player's perspective.",
              "4: in doubles, listen from the fourth player's perspective.")
          ]
        when "es"
          [
            rule_section(:goal, "El objetivo del partido",
              "En Axel Pong mueves una paleta para defender tu porter\u00EDa y devolver la pelota hacia un lugar que el rival no alcance. Si la pelota entra en tu porter\u00EDa, el rival gana un punto. En individuales juegan dos personas; tambi\u00E9n puedes jugar contra un bot.",
              "El sonido permite seguir la pelota: se oye a la izquierda o a la derecha seg\u00FAn su posici\u00F3n respecto a tu paleta, y aumenta de volumen al acercarse. Los auriculares ayudan a distinguir estas se\u00F1ales."),
            rule_section(:rally, "Mover la paleta y golpear",
              "Mueve la paleta con las flechas izquierda y derecha. Mant\u00E9n la tecla pulsada para recorrer una distancia mayor.",
              "Su sonido de movimiento es grave cerca de las paredes laterales y se vuelve m\u00E1s agudo al acercarse al centro. Despu\u00E9s de cruzar el centro vuelve a bajar de tono. Pulsa C para consultar la posici\u00F3n de la paleta.",
              "Cuando debas sacar, pulsa flecha arriba o Espacio. La pelota sale desde la posici\u00F3n de tu paleta. Si mantienes flecha izquierda o derecha al sacar, la enviar\u00E1s en diagonal.",
              "Para devolver un golpe, lleva la paleta a la trayectoria de la pelota. Cuando est\u00E9 cerca y a su alcance, pulsa flecha arriba o Espacio. Estar en el lugar correcto no basta: tambi\u00E9n hay que golpear en el momento adecuado.",
              "La parte de la paleta que toca la pelota determina la direcci\u00F3n de la devoluci\u00F3n:",
              "- Con el centro, la pelota sale recta.",
              "- Con la parte izquierda, sale en diagonal hacia la izquierda.",
              "- Con la parte derecha, sale en diagonal hacia la derecha.",
              "Usa estas direcciones para buscar un hueco en la defensa rival. La pelota acelera con cada devoluci\u00F3n.",
              "La pelota tambi\u00E9n rebota en las paredes laterales. Cuanto m\u00E1s cerca de ti ocurra el rebote, m\u00E1s agudo ser\u00E1 su sonido; junto a la porter\u00EDa rival es donde suena m\u00E1s grave."),
            rule_section(:points, "Saques y puntuaci\u00F3n",
              "Contra un bot, t\u00FA haces el primer saque. Entre dos personas, el juego anuncia qui\u00E9n empieza. A partir de ah\u00ED, el saque cambia de lado cada dos puntos. Pulsa T para saber a qui\u00E9n le toca.",
              "Gana quien alcance al menos 11 puntos con dos de ventaja. El partido contin\u00FAa con 11:10, pero termina con 12:10. Consulta el marcador con S.",
              "En un partido sin bots, si el rival tarda en sacar puedes apremiarlo con Ctrl+W. Dispondr\u00E1 de diez segundos para iniciar el intercambio; si no lo hace, ganas el punto. Deben pasar quince segundos antes de volver a apremiarlo."),
            rule_section(:doubles, "Dobles",
              "En los ajustes de la mesa puedes elegir dobles en lugar de individuales. Se forman dos equipos de dos personas. Compartes porter\u00EDa y marcador con tu compa\u00F1ero, pero cada uno mueve su propia paleta.",
              "Los compa\u00F1eros se alternan al golpear. Si sacas t\u00FA, el orden del intercambio es este:",
              "1. Uno de los rivales devuelve tu saque.",
              "2. Tu compa\u00F1ero devuelve esa pelota.",
              "3. Golpea el otro rival.",
              "4. Te toca golpear a ti.",
              "El orden se repite hasta que alguien gana el punto. No puedes devolver una pelota que le corresponde a tu compa\u00F1ero, aunque la tengas m\u00E1s cerca.",
              "Se sortea el equipo que empieza sacando. Cada dos puntos cambian tanto quien saca como quien recibe. El juego anuncia la pareja de saque y recepci\u00F3n, que tambi\u00E9n puedes consultar con T. S lee los equipos y el marcador.",
              "Las dos paletas de un equipo tienen sonidos de movimiento diferentes. Adem\u00E1s, el primer jugador de cada equipo tiene un sonido de saque y de golpe m\u00E1s grave que el segundo."),
            rule_section(:arcade, "Modo Arcade",
              "El modo habitual se llama Classic. Si eliges Arcade en los ajustes de la mesa, cada devoluci\u00F3n con la paleta puede activar efectos especiales. Tiene un 7 % de probabilidad de dar un escudo y, por separado, un 7 % de volver invisible la pelota; por eso pueden aparecer ambos a la vez. Los saques no activan efectos.",
              "- El escudo protege todo tu borde durante diez segundos de juego. Si la pelota supera la paleta, el escudo la devuelve recta y sigue activo. Otro escudo renueva su duraci\u00F3n. En dobles protege a ambos compa\u00F1eros. El tiempo no corre mientras se espera un saque, y la protecci\u00F3n que quede pasa al punto siguiente.",
              "- La pelota invisible deja de o\u00EDrse. Tendr\u00E1s que prever por d\u00F3nde viene para colocar la paleta. Al golpearla con una paleta vuelve su sonido; un rebote en el escudo no lo recupera. La invisibilidad tambi\u00E9n termina al acabar el punto.",
              "Pulsa E para consultar los efectos activos."),
            rule_section(:options, "Dificultad y duraci\u00F3n",
              "La dificultad se elige antes de jugar, en los ajustes de la mesa. Por defecto es Normal. Los niveles f\u00E1ciles hacen m\u00E1s lenta la pelota; los dif\u00EDciles la aceleran y tambi\u00E9n mejoran el juego del bot.",
              "Puedes cambiar la meta de 11 puntos por 7 o 21, o introducir otra con la opci\u00F3n de n\u00FAmero personalizado. En todos los casos se necesitan dos puntos de ventaja.",
              "La opci\u00F3n de partida infinita mantiene el marcador sin que este ponga fin al partido. En ese caso, el anfitri\u00F3n termina la partida con Ctrl+Q."),
            rule_section(:personal, "Rat\u00F3n, ayuda de golpeo y sonidos",
              "Tambi\u00E9n puedes jugar con rat\u00F3n o panel t\u00E1ctil. Despl\u00E1zalo a izquierda y derecha para mover la paleta y usa el bot\u00F3n izquierdo para sacar y golpear. Este control est\u00E1 disponible directamente en el campo de juego.",
              "Con Ctrl+P abres tus ajustes de Pong:",
              "- El golpeo autom\u00E1tico devuelve las pelotas que est\u00E9n al alcance de la paleta. T\u00FA sigues movi\u00E9ndola y realizando los saques. Esta ayuda est\u00E1 desactivada al principio.",
              "- El volumen de tu paleta permite atenuar o aumentar el sonido de tu movimiento.",
              "- El volumen de la paleta rival ajusta el sonido de su movimiento.",
              "- El volumen de la voz ajusta los anuncios hablados del juego.",
              "Adem\u00E1s, Shift+E alterna entre ruido, tonos y silencio para las se\u00F1ales de los bordes laterales. La se\u00F1al de cada borde aumenta de volumen cuanto m\u00E1s cerca est\u00E1 tu paleta."),
            rule_section(:credits, "Origen del juego",
              "Axel Pong no es un juego original de papierek. Naci\u00F3 como Dragon-Pong y despu\u00E9s Axel y balteam lo mejoraron. Se adapt\u00F3 a ELTEN con su permiso."),
            rule_section(:controls, "Teclas de referencia",
              "Flecha izquierda: mover la paleta a la izquierda.",
              "Flecha derecha: mover la paleta a la derecha.",
              "Flecha arriba: sacar o golpear.",
              "Espacio: sacar o golpear.",
              "Bot\u00F3n izquierdo del rat\u00F3n: sacar o golpear.",
              "C: consultar la posici\u00F3n de tu paleta o la del jugador que observas.",
              "S: consultar el marcador y, en dobles, los equipos.",
              "T: consultar qui\u00E9n saca y el estado de la conexi\u00F3n; en dobles, tambi\u00E9n qui\u00E9n recibe.",
              "Ctrl+W: apremiar al rival que debe sacar.",
              "E: consultar los efectos de Arcade activos.",
              "Shift+E: cambiar las se\u00F1ales de los bordes laterales.",
              "Ctrl+P: abrir los ajustes de Pong.",
              "1: como espectador, escuchar desde el punto de vista del primer jugador.",
              "2: como espectador, escuchar desde el punto de vista del segundo jugador.",
              "3: como espectador de dobles, escuchar desde el punto de vista del tercer jugador.",
              "4: como espectador de dobles, escuchar desde el punto de vista del cuarto jugador.")
          ]
        when "pl"
          [
            rule_section(:goal, "Na czym polega gra",
              "W Axel Pongu odbijasz pi\u0142k\u0119 rakietk\u0105 i pr\u00F3bujesz pos\u0142a\u0107 j\u0105 tak, \u017Ceby przeciwnik nie zd\u0105\u017Cy\u0142 jej odebra\u0107. Rakietk\u0105 bronisz swojej bramki. Gdy pi\u0142ka do niej wpadnie, przeciwnik zdobywa punkt. W singlu graj\u0105 dwie osoby; mo\u017Cesz te\u017C zmierzy\u0107 si\u0119 z botem.",
              "Pi\u0142k\u0119 s\u0142ycha\u0107 z lewej lub z prawej zale\u017Cnie od tego, gdzie znajduje si\u0119 wzgl\u0119dem twojej rakietki. W miar\u0119 zbli\u017Cania si\u0119 staje si\u0119 g\u0142o\u015Bniejsza. W s\u0142uchawkach \u0142atwiej \u015Bledzi\u0107 oba te sygna\u0142y."),
            rule_section(:rally, "Sterowanie rakietk\u0105 i odbijanie",
              "Przesuwaj rakietk\u0119 strza\u0142kami w lewo i w prawo. Klawisz mo\u017Cna przytrzyma\u0107, je\u015Bli chcesz pokona\u0107 wi\u0119ksz\u0105 odleg\u0142o\u015B\u0107.",
              "Przy bocznych \u015Bcianach, nazywanych bandami, d\u017Awi\u0119k ruchu rakietki jest niski. Im bli\u017Cej \u015Brodka sto\u0142u, tym staje si\u0119 wy\u017Cszy. Po mini\u0119ciu \u015Brodka zn\u00F3w si\u0119 obni\u017Ca. Klawisz C podaje pozycj\u0119 rakietki.",
              "Gdy wypada tw\u00F3j serwis, naci\u015Bnij strza\u0142k\u0119 w g\u00F3r\u0119 albo Spacj\u0119. Pi\u0142ka wyleci od miejsca, w kt\u00F3rym stoi rakietka. \u017Beby pos\u0142a\u0107 j\u0105 po skosie, przytrzymaj podczas serwu strza\u0142k\u0119 w lewo lub w prawo.",
              "Po uderzeniu przeciwnika ustaw rakietk\u0119 na drodze pi\u0142ki. Kiedy pi\u0142ka znajdzie si\u0119 blisko ciebie, naci\u015Bnij strza\u0142k\u0119 w g\u00F3r\u0119 lub Spacj\u0119, \u017Ceby j\u0105 odbi\u0107. Samo ustawienie rakietki nie wystarcza \u2014 odbijasz dopiero wtedy, gdy pi\u0142ka jest w jej zasi\u0119gu.",
              "Kierunek odbicia zale\u017Cy od miejsca, w kt\u00F3rym pi\u0142ka trafi w rakietk\u0119:",
              "- \u015Arodkiem odbijesz pi\u0142k\u0119 na wprost.",
              "- Lew\u0105 cz\u0119\u015Bci\u0105 po\u015Blesz j\u0105 uko\u015Bnie w lewo.",
              "- Praw\u0105 cz\u0119\u015Bci\u0105 po\u015Blesz j\u0105 uko\u015Bnie w prawo.",
              "W ten spos\u00F3b mo\u017Cesz celowa\u0107 w miejsce, kt\u00F3rego przeciwnik nie pilnuje. Z ka\u017Cdym odbiciem pi\u0142ka przyspiesza.",
              "Pi\u0142ka mo\u017Ce odbija\u0107 si\u0119 od band. Im bli\u017Cej ciebie nast\u0105pi takie odbicie, tym wy\u017Cszy d\u017Awi\u0119k us\u0142yszysz. Przy bramce przeciwnika jest on najni\u017Cszy."),
            rule_section(:points, "Serwisy i wynik meczu",
              "Przeciwko botowi serwujesz jako pierwszy. W meczu dw\u00F3ch os\u00F3b us\u0142yszysz, kto zaczyna. Potem serwis przechodzi na drug\u0105 stron\u0119 co dwa punkty. Klawiszem T sprawdzisz, kto ma serwowa\u0107.",
              "Wygrywasz, gdy masz co najmniej 11 punkt\u00F3w i przewag\u0119 dw\u00F3ch nad przeciwnikiem. Przy 11:10 mecz trwa dalej; wynik 12:10 ju\u017C go ko\u0144czy. S pozwala sprawdzi\u0107 bie\u017C\u0105c\u0105 punktacj\u0119.",
              "Je\u017Celi w meczu bez bot\u00F3w przeciwnik zwleka z serwisem, mo\u017Cesz nacisn\u0105\u0107 Ctrl+W. Dostaje dziesi\u0119\u0107 sekund na rozpocz\u0119cie wymiany. Je\u015Bli tego nie zrobi, zdob\u0119dziesz punkt. Kolejne ponaglenie jest dost\u0119pne po pi\u0119tnastu sekundach."),
            rule_section(:doubles, "Gra w deblu",
              "W ustawieniach sto\u0142u mo\u017Cna zamiast singla wybra\u0107 debel. Graj\u0105 wtedy dwie dru\u017Cyny po dwie osoby. Z partnerem bronicie wsp\u00F3lnej bramki i razem zdobywacie punkty, ale ka\u017Cdy porusza w\u0142asn\u0105 rakietk\u0105.",
              "Partnerzy odbijaj\u0105 na zmian\u0119. Je\u015Bli to ty serwujesz, wymiana wygl\u0105da nast\u0119puj\u0105co:",
              "1. Serwis odbiera jeden z przeciwnik\u00F3w.",
              "2. Odes\u0142an\u0105 pi\u0142k\u0119 odbija tw\u00F3j partner.",
              "3. Nast\u0119pnie odbija drugi przeciwnik.",
              "4. Kolejna pi\u0142ka nale\u017Cy do ciebie.",
              "Ta kolejno\u015B\u0107 powtarza si\u0119 do zdobycia punktu. Nie mo\u017Cesz odbi\u0107 pi\u0142ki za partnera, nawet je\u015Bli jeste\u015B bli\u017Cej niej.",
              "Serwuj\u0105ca dru\u017Cyna jest losowana na pocz\u0105tku meczu. Co dwa punkty zmieniaj\u0105 si\u0119 serwuj\u0105cy i odbieraj\u0105cy. Gra zapowiada, kto serwuje do kogo; mo\u017Cesz to r\u00F3wnie\u017C sprawdzi\u0107 klawiszem T. S odczytuje sk\u0142ady dru\u017Cyn i wynik.",
              "Ruch rakietki ka\u017Cdego z partner\u00F3w brzmi inaczej, dzi\u0119ki czemu mo\u017Cesz ich odr\u00F3\u017Cni\u0107. Pierwsza osoba w ka\u017Cdej dru\u017Cynie ma te\u017C ni\u017Cszy d\u017Awi\u0119k serwisu i odbicia ni\u017C druga."),
            rule_section(:arcade, "Tryb Arcade",
              "Zwyk\u0142y tryb nazywa si\u0119 Classic. W ustawieniach sto\u0142u mo\u017Cesz zamieni\u0107 go na Arcade, w kt\u00F3rym odbicie rakietk\u0105 mo\u017Ce uruchomi\u0107 dodatkowy efekt. Ka\u017Cde odbicie ma osobno 7% szans na tarcz\u0119 i 7% na niewidzialn\u0105 pi\u0142k\u0119, wi\u0119c czasem pojawi\u0105 si\u0119 oba efekty. Nie losuje si\u0119 ich przy serwisie. Efekty dzia\u0142aj\u0105 nast\u0119puj\u0105co:",
              "- Tarcza przez dziesi\u0119\u0107 sekund gry chroni ca\u0142\u0105 twoj\u0105 kraw\u0119d\u017A. Je\u015Bli przepu\u015Bcisz pi\u0142k\u0119, tarcza odbije j\u0105 prosto i nadal b\u0119dzie dzia\u0142a\u0107. Kolejna tarcza odnawia czas ochrony. W deblu chronieni s\u0105 obaj partnerzy. Czas tarczy nie ubywa podczas czekania na serwis, a niewykorzystana cz\u0119\u015B\u0107 ochrony przechodzi do nast\u0119pnego punktu.",
              "- Niewidzialnej pi\u0142ki nie s\u0142ycha\u0107. Musisz przewidzie\u0107 jej lot i spr\u00F3bowa\u0107 ustawi\u0107 rakietk\u0119 we w\u0142a\u015Bciwym miejscu. Ponowne odbicie rakietk\u0105 przywraca d\u017Awi\u0119k; odbicie tarcz\u0105 tego nie robi. Efekt ko\u0144czy si\u0119 tak\u017Ce wraz z punktem.",
              "E odczytuje, kt\u00F3re efekty s\u0105 aktywne."),
            rule_section(:options, "Szybko\u015B\u0107 i liczba punkt\u00F3w",
              "Poziom trudno\u015Bci wybierasz przed gr\u0105 w ustawieniach sto\u0142u. Domy\u015Blnie jest to Normalny. Na \u0142atwiejszym poziomie pi\u0142ka porusza si\u0119 wolniej, a na trudniejszych coraz szybciej. Na wy\u017Cszych poziomach bot r\u00F3wnie\u017C gra lepiej.",
              "W tych samych ustawieniach mo\u017Cna wybra\u0107 gr\u0119 do 7 lub 21 punkt\u00F3w zamiast do 11. Opcja \u201EW\u0142asna liczba\u201D pozwala wpisa\u0107 inny cel. Nadal potrzeba dw\u00F3ch punkt\u00F3w przewagi.",
              "Mo\u017Cesz te\u017C wybra\u0107 \u201ENiesko\u0144czony\u201D. Wynik b\u0119dzie wtedy liczony, ale nie zako\u0144czy meczu. Gospodarz ko\u0144czy tak\u0105 parti\u0119 skr\u00F3tem Ctrl+Q."),
            rule_section(:personal, "Mysz, automatyczne odbijanie i d\u017Awi\u0119ki",
              "Je\u015Bli wolisz mysz, przesuwaj j\u0105 w lewo i w prawo, a lewym przyciskiem serwuj i odbijaj. Ten spos\u00F3b sterowania jest od razu dost\u0119pny na polu gry Ponga. Mo\u017Cesz tak gra\u0107 r\u00F3wnie\u017C touchpadem.",
              "Ctrl+P otwiera twoje ustawienia Ponga. Znajdziesz w nich nast\u0119puj\u0105ce opcje:",
              "- Automatyczne odbijanie sprawia, \u017Ce rakietka sama odbija pi\u0142k\u0119 znajduj\u0105c\u0105 si\u0119 w jej zasi\u0119gu. Wci\u0105\u017C trzeba przesuwa\u0107 rakietk\u0119 i wykonywa\u0107 serwisy. Pocz\u0105tkowo ta pomoc jest wy\u0142\u0105czona.",
              "- G\u0142o\u015Bno\u015B\u0107 w\u0142asnej rakietki pozwala wyciszy\u0107 lub wzmocni\u0107 d\u017Awi\u0119k twojego ruchu.",
              "- G\u0142o\u015Bno\u015B\u0107 rakietki przeciwnika reguluje d\u017Awi\u0119k jego ruchu.",
              "- G\u0142o\u015Bno\u015B\u0107 lektora dotyczy g\u0142osowych zapowiedzi w grze.",
              "Dodatkowo Shift+E prze\u0142\u0105cza d\u017Awi\u0119ki bocznych kraw\u0119dzi: szum, tony lub wy\u0142\u0105czenie. Im bli\u017Cej danej kraw\u0119dzi stoi rakietka, tym g\u0142o\u015Bniej s\u0142ycha\u0107 jej sygna\u0142."),
            rule_section(:credits, "Pochodzenie gry",
              "Axel Pong nie jest autorsk\u0105 gr\u0105 papierka. Powsta\u0142 jako Dragon-Pong, nast\u0119pnie zosta\u0142 ulepszony przez Axela i balteama. Do ELTEN-a przeniesiono go za ich zgod\u0105."),
            rule_section(:controls, "Skr\u00F3ty klawiszowe",
              "Strza\u0142ka w lewo: przesu\u0144 rakietk\u0119 w lewo.",
              "Strza\u0142ka w prawo: przesu\u0144 rakietk\u0119 w prawo.",
              "Strza\u0142ka w g\u00F3r\u0119: zaserwuj lub odbij pi\u0142k\u0119.",
              "Spacja: zaserwuj lub odbij pi\u0142k\u0119.",
              "Lewy przycisk myszy: zaserwuj lub odbij pi\u0142k\u0119.",
              "C: odczytaj po\u0142o\u017Cenie swojej rakietki lub rakietki obserwowanego gracza.",
              "S: odczytaj wynik, a w deblu tak\u017Ce dru\u017Cyny.",
              "T: odczytaj serwuj\u0105cego i stan po\u0142\u0105czenia, a w deblu tak\u017Ce odbieraj\u0105cego.",
              "Ctrl+W: ponaglij przeciwnika przed serwisem.",
              "E: odczytaj aktywne efekty Arcade.",
              "Shift+E: prze\u0142\u0105cz d\u017Awi\u0119ki bocznych kraw\u0119dzi.",
              "Ctrl+P: otw\u00F3rz ustawienia Ponga.",
              "1: jako obserwator s\u0142uchaj z perspektywy pierwszego gracza.",
              "2: jako obserwator s\u0142uchaj z perspektywy drugiego gracza.",
              "3: jako obserwator debla s\u0142uchaj z perspektywy trzeciego gracza.",
              "4: jako obserwator debla s\u0142uchaj z perspektywy czwartego gracza.")
          ]
        when "ru"
          [
            rule_section(:goal, "\u0421\u0443\u0442\u044C \u0438\u0433\u0440\u044B",
              "\u0412 Axel Pong \u0432\u044B \u043E\u0442\u0431\u0438\u0432\u0430\u0435\u0442\u0435 \u043C\u044F\u0447 \u0440\u0430\u043A\u0435\u0442\u043A\u043E\u0439, \u0441\u0442\u0430\u0440\u0430\u044F\u0441\u044C \u043D\u0430\u043F\u0440\u0430\u0432\u0438\u0442\u044C \u0435\u0433\u043E \u0442\u0443\u0434\u0430, \u0433\u0434\u0435 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A \u043D\u0435 \u0443\u0441\u043F\u0435\u0435\u0442 \u043F\u0440\u0438\u043D\u044F\u0442\u044C \u0443\u0434\u0430\u0440. \u0412\u0430\u0448\u0430 \u0440\u0430\u043A\u0435\u0442\u043A\u0430 \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u0432\u043E\u0440\u043E\u0442\u0430: \u043F\u0440\u043E\u043F\u0443\u0441\u0442\u0438\u0432 \u0432 \u043D\u0438\u0445 \u043C\u044F\u0447, \u0432\u044B \u043E\u0442\u0434\u0430\u0451\u0442\u0435 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0443 \u043E\u0447\u043A\u043E. \u0412 \u043E\u0434\u0438\u043D\u043E\u0447\u043D\u043E\u043C \u043C\u0430\u0442\u0447\u0435 \u0443\u0447\u0430\u0441\u0442\u0432\u0443\u044E\u0442 \u0434\u0432\u0430 \u0438\u0433\u0440\u043E\u043A\u0430; \u043C\u043E\u0436\u043D\u043E \u0438\u0433\u0440\u0430\u0442\u044C \u0438 \u043F\u0440\u043E\u0442\u0438\u0432 \u0431\u043E\u0442\u0430.",
              "\u041F\u043E \u0437\u0432\u0443\u043A\u0443 \u0441\u043B\u044B\u0448\u043D\u043E, \u0441\u043B\u0435\u0432\u0430 \u0438\u043B\u0438 \u0441\u043F\u0440\u0430\u0432\u0430 \u043E\u0442 \u0440\u0430\u043A\u0435\u0442\u043A\u0438 \u043D\u0430\u0445\u043E\u0434\u0438\u0442\u0441\u044F \u043C\u044F\u0447. \u0427\u0435\u043C \u043E\u043D \u0431\u043B\u0438\u0436\u0435, \u0442\u0435\u043C \u0433\u0440\u043E\u043C\u0447\u0435 \u0437\u0432\u0443\u0447\u0438\u0442. \u041D\u0430\u0443\u0448\u043D\u0438\u043A\u0438 \u043F\u043E\u043C\u043E\u0433\u0430\u044E\u0442 \u0441\u043B\u0435\u0434\u0438\u0442\u044C \u0438 \u0437\u0430 \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435\u043C, \u0438 \u0437\u0430 \u0440\u0430\u0441\u0441\u0442\u043E\u044F\u043D\u0438\u0435\u043C."),
            rule_section(:rally, "\u0414\u0432\u0438\u0436\u0435\u043D\u0438\u0435 \u0440\u0430\u043A\u0435\u0442\u043A\u0438 \u0438 \u0443\u0434\u0430\u0440\u044B",
              "\u041F\u0435\u0440\u0435\u043C\u0435\u0449\u0430\u0439\u0442\u0435 \u0440\u0430\u043A\u0435\u0442\u043A\u0443 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0432\u043B\u0435\u0432\u043E \u0438 \u0432\u043F\u0440\u0430\u0432\u043E. \u0427\u0442\u043E\u0431\u044B \u043F\u0440\u043E\u0439\u0442\u0438 \u0431\u043E\u043B\u044C\u0448\u043E\u0435 \u0440\u0430\u0441\u0441\u0442\u043E\u044F\u043D\u0438\u0435, \u0443\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0439\u0442\u0435 \u043D\u0443\u0436\u043D\u0443\u044E \u0441\u0442\u0440\u0435\u043B\u043A\u0443.",
              "\u0412\u043E\u0437\u043B\u0435 \u0431\u043E\u043A\u043E\u0432\u044B\u0445 \u0441\u0442\u0435\u043D\u043E\u043A, \u0438\u043B\u0438 \u0431\u043E\u0440\u0442\u043E\u0432, \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435 \u0440\u0430\u043A\u0435\u0442\u043A\u0438 \u0441\u043E\u043F\u0440\u043E\u0432\u043E\u0436\u0434\u0430\u0435\u0442\u0441\u044F \u043D\u0438\u0437\u043A\u0438\u043C \u0437\u0432\u0443\u043A\u043E\u043C. \u041F\u043E \u043C\u0435\u0440\u0435 \u043F\u0440\u0438\u0431\u043B\u0438\u0436\u0435\u043D\u0438\u044F \u043A \u0446\u0435\u043D\u0442\u0440\u0443 \u0437\u0432\u0443\u043A \u043F\u043E\u0432\u044B\u0448\u0430\u0435\u0442\u0441\u044F, \u0430 \u043F\u043E\u0441\u043B\u0435 \u043F\u0440\u043E\u0445\u043E\u0436\u0434\u0435\u043D\u0438\u044F \u0446\u0435\u043D\u0442\u0440\u0430 \u0441\u043D\u043E\u0432\u0430 \u043F\u043E\u043D\u0438\u0436\u0430\u0435\u0442\u0441\u044F. \u041A\u043B\u0430\u0432\u0438\u0448\u0430 C \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u0440\u0430\u043A\u0435\u0442\u043A\u0438.",
              "\u0414\u043B\u044F \u043F\u043E\u0434\u0430\u0447\u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 \u0441\u0442\u0440\u0435\u043B\u043A\u0443 \u0432\u0432\u0435\u0440\u0445 \u0438\u043B\u0438 \u041F\u0440\u043E\u0431\u0435\u043B. \u041C\u044F\u0447 \u0432\u044B\u043B\u0435\u0442\u0438\u0442 \u043E\u0442 \u0432\u0430\u0448\u0435\u0439 \u0440\u0430\u043A\u0435\u0442\u043A\u0438. \u0415\u0441\u043B\u0438 \u0445\u043E\u0442\u0438\u0442\u0435 \u043F\u043E\u0434\u0430\u0442\u044C \u043F\u043E \u0434\u0438\u0430\u0433\u043E\u043D\u0430\u043B\u0438, \u043E\u0434\u043D\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u043E \u0443\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0439\u0442\u0435 \u0441\u0442\u0440\u0435\u043B\u043A\u0443 \u0432\u043B\u0435\u0432\u043E \u0438\u043B\u0438 \u0432\u043F\u0440\u0430\u0432\u043E.",
              "\u041F\u043E\u0441\u043B\u0435 \u0443\u0434\u0430\u0440\u0430 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u043F\u0435\u0440\u0435\u043C\u0435\u0441\u0442\u0438\u0442\u0435 \u0440\u0430\u043A\u0435\u0442\u043A\u0443 \u043D\u0430 \u043F\u0443\u0442\u0438 \u043C\u044F\u0447\u0430. \u041A\u043E\u0433\u0434\u0430 \u043C\u044F\u0447 \u043F\u0440\u0438\u0431\u043B\u0438\u0437\u0438\u0442\u0441\u044F, \u043D\u0430\u0436\u043C\u0438\u0442\u0435 \u0441\u0442\u0440\u0435\u043B\u043A\u0443 \u0432\u0432\u0435\u0440\u0445 \u0438\u043B\u0438 \u041F\u0440\u043E\u0431\u0435\u043B, \u0447\u0442\u043E\u0431\u044B \u0435\u0433\u043E \u043E\u0442\u0431\u0438\u0442\u044C. \u041E\u0434\u043D\u043E\u0433\u043E \u0432\u0435\u0440\u043D\u043E\u0433\u043E \u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u044F \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043E\u0447\u043D\u043E: \u0443\u0434\u0430\u0440 \u043D\u0443\u0436\u043D\u043E \u0441\u0434\u0435\u043B\u0430\u0442\u044C, \u043F\u043E\u043A\u0430 \u043C\u044F\u0447 \u043D\u0430\u0445\u043E\u0434\u0438\u0442\u0441\u044F \u0432 \u043F\u0440\u0435\u0434\u0435\u043B\u0430\u0445 \u0434\u043E\u0441\u044F\u0433\u0430\u0435\u043C\u043E\u0441\u0442\u0438 \u0440\u0430\u043A\u0435\u0442\u043A\u0438.",
              "\u041D\u0430\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u043E\u0442\u0432\u0435\u0442\u043D\u043E\u0433\u043E \u0443\u0434\u0430\u0440\u0430 \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043E\u0442 \u0442\u043E\u0433\u043E, \u043A\u0430\u043A\u043E\u0439 \u0447\u0430\u0441\u0442\u044C\u044E \u0440\u0430\u043A\u0435\u0442\u043A\u0438 \u0432\u044B \u0432\u0441\u0442\u0440\u0435\u0442\u0438\u043B\u0438 \u043C\u044F\u0447:",
              "- \u0421\u0435\u0440\u0435\u0434\u0438\u043D\u0430 \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u044F\u0435\u0442 \u043C\u044F\u0447 \u043F\u0440\u044F\u043C\u043E.",
              "- \u041B\u0435\u0432\u0430\u044F \u0447\u0430\u0441\u0442\u044C \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u044F\u0435\u0442 \u0435\u0433\u043E \u0432\u043B\u0435\u0432\u043E \u043F\u043E \u0434\u0438\u0430\u0433\u043E\u043D\u0430\u043B\u0438.",
              "- \u041F\u0440\u0430\u0432\u0430\u044F \u0447\u0430\u0441\u0442\u044C \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u044F\u0435\u0442 \u0435\u0433\u043E \u0432\u043F\u0440\u0430\u0432\u043E \u043F\u043E \u0434\u0438\u0430\u0433\u043E\u043D\u0430\u043B\u0438.",
              "\u041C\u0435\u043D\u044F\u044F \u043C\u0435\u0441\u0442\u043E \u0443\u0434\u0430\u0440\u0430, \u043C\u043E\u0436\u043D\u043E \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u044F\u0442\u044C \u043C\u044F\u0447 \u0432 \u043D\u0435\u0437\u0430\u043A\u0440\u044B\u0442\u0443\u044E \u0447\u0430\u0441\u0442\u044C \u0432\u043E\u0440\u043E\u0442 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430. \u041F\u043E\u0441\u043B\u0435 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0443\u0434\u0430\u0440\u0430 \u043C\u044F\u0447 \u0443\u0441\u043A\u043E\u0440\u044F\u0435\u0442\u0441\u044F.",
              "\u041C\u044F\u0447 \u0442\u0430\u043A\u0436\u0435 \u043E\u0442\u0441\u043A\u0430\u043A\u0438\u0432\u0430\u0435\u0442 \u043E\u0442 \u0431\u043E\u0440\u0442\u043E\u0432. \u0412\u044B\u0441\u043E\u0442\u0430 \u0437\u0432\u0443\u043A\u0430 \u0442\u0430\u043A\u043E\u0433\u043E \u043E\u0442\u0441\u043A\u043E\u043A\u0430 \u043F\u043E\u0434\u0441\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442, \u043D\u0430\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0431\u043B\u0438\u0437\u043A\u043E \u043E\u043D \u043F\u0440\u043E\u0438\u0437\u043E\u0448\u0451\u043B: \u0432\u043E\u0437\u043B\u0435 \u0432\u0430\u0448\u0438\u0445 \u0432\u043E\u0440\u043E\u0442 \u0437\u0432\u0443\u043A \u0441\u0430\u043C\u044B\u0439 \u0432\u044B\u0441\u043E\u043A\u0438\u0439, \u0432\u043E\u0437\u043B\u0435 \u0447\u0443\u0436\u0438\u0445 \u2014 \u0441\u0430\u043C\u044B\u0439 \u043D\u0438\u0437\u043A\u0438\u0439."),
            rule_section(:points, "\u041F\u043E\u0434\u0430\u0447\u0430 \u0438 \u0441\u0447\u0451\u0442",
              "\u041F\u0440\u043E\u0442\u0438\u0432 \u0431\u043E\u0442\u0430 \u043F\u0435\u0440\u0432\u044B\u043C \u043F\u043E\u0434\u0430\u0451\u0442\u0435 \u0432\u044B. \u0412 \u043C\u0430\u0442\u0447\u0435 \u043C\u0435\u0436\u0434\u0443 \u043B\u044E\u0434\u044C\u043C\u0438 \u0438\u0433\u0440\u0430 \u043E\u0431\u044A\u044F\u0432\u0438\u0442 \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u043F\u043E\u0434\u0430\u044E\u0449\u0435\u0433\u043E. \u0417\u0430\u0442\u0435\u043C \u043F\u043E\u0434\u0430\u0447\u0430 \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u0438\u0442 \u043D\u0430 \u0434\u0440\u0443\u0433\u0443\u044E \u0441\u0442\u043E\u0440\u043E\u043D\u0443 \u0447\u0435\u0440\u0435\u0437 \u043A\u0430\u0436\u0434\u044B\u0435 \u0434\u0432\u0430 \u043E\u0447\u043A\u0430. \u041F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C, \u043A\u0442\u043E \u043F\u043E\u0434\u0430\u0451\u0442 \u0441\u0435\u0439\u0447\u0430\u0441, \u043C\u043E\u0436\u043D\u043E \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 T.",
              "\u0414\u043B\u044F \u043F\u043E\u0431\u0435\u0434\u044B \u043D\u0443\u0436\u043D\u044B \u0445\u043E\u0442\u044F \u0431\u044B 11 \u043E\u0447\u043A\u043E\u0432 \u0438 \u043F\u0440\u0435\u0438\u043C\u0443\u0449\u0435\u0441\u0442\u0432\u043E \u0432 \u0434\u0432\u0430. \u0421\u0447\u0451\u0442 11:10 \u0435\u0449\u0451 \u043D\u0435 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442 \u043C\u0430\u0442\u0447, \u0430 12:10 \u2014 \u0443\u0436\u0435 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442. \u0422\u0435\u043A\u0443\u0449\u0438\u0439 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u043A\u043B\u0430\u0432\u0438\u0448\u0430 S.",
              "\u0415\u0441\u043B\u0438 \u0432 \u043C\u0430\u0442\u0447\u0435 \u0431\u0435\u0437 \u0431\u043E\u0442\u043E\u0432 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A \u0437\u0430\u0442\u044F\u0433\u0438\u0432\u0430\u0435\u0442 \u043F\u043E\u0434\u0430\u0447\u0443, \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Ctrl+W. \u0415\u043C\u0443 \u043E\u0442\u0432\u043E\u0434\u0438\u0442\u0441\u044F \u0434\u0435\u0441\u044F\u0442\u044C \u0441\u0435\u043A\u0443\u043D\u0434 \u043D\u0430 \u043D\u0430\u0447\u0430\u043B\u043E \u0440\u043E\u0437\u044B\u0433\u0440\u044B\u0448\u0430; \u0438\u043D\u0430\u0447\u0435 \u043E\u0447\u043A\u043E \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u0435 \u0432\u044B. \u041F\u043E\u0432\u0442\u043E\u0440\u043D\u043E \u043F\u043E\u0442\u043E\u0440\u043E\u043F\u0438\u0442\u044C \u0435\u0433\u043E \u043C\u043E\u0436\u043D\u043E \u0447\u0435\u0440\u0435\u0437 \u043F\u044F\u0442\u043D\u0430\u0434\u0446\u0430\u0442\u044C \u0441\u0435\u043A\u0443\u043D\u0434."),
            rule_section(:doubles, "\u041F\u0430\u0440\u043D\u044B\u0439 \u043C\u0430\u0442\u0447",
              "\u0412\u043C\u0435\u0441\u0442\u043E \u043E\u0434\u0438\u043D\u043E\u0447\u043D\u043E\u0439 \u0438\u0433\u0440\u044B \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0441\u0442\u043E\u043B\u0430 \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u043F\u0430\u0440\u043D\u0443\u044E. \u0414\u0432\u0435 \u043A\u043E\u043C\u0430\u043D\u0434\u044B \u043F\u043E \u0434\u0432\u0430 \u0438\u0433\u0440\u043E\u043A\u0430 \u0441\u043E\u0440\u0435\u0432\u043D\u0443\u044E\u0442\u0441\u044F \u0437\u0430 \u043E\u0447\u043A\u0438. \u0423 \u0432\u0430\u0441 \u0441 \u043F\u0430\u0440\u0442\u043D\u0451\u0440\u043E\u043C \u043E\u0431\u0449\u0438\u0435 \u0432\u043E\u0440\u043E\u0442\u0430 \u0438 \u0441\u0447\u0451\u0442, \u043D\u043E \u043A\u0430\u0436\u0434\u044B\u0439 \u0443\u043F\u0440\u0430\u0432\u043B\u044F\u0435\u0442 \u0441\u0432\u043E\u0435\u0439 \u0440\u0430\u043A\u0435\u0442\u043A\u043E\u0439.",
              "\u0412 \u043A\u043E\u043C\u0430\u043D\u0434\u0435 \u0443\u0434\u0430\u0440\u044B \u043D\u0430\u043D\u043E\u0441\u044F\u0442 \u043F\u043E \u043E\u0447\u0435\u0440\u0435\u0434\u0438. \u0415\u0441\u043B\u0438 \u043F\u043E\u0434\u0430\u043B\u0438 \u0432\u044B, \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u043F\u0440\u0438\u043D\u0438\u043C\u0430\u0435\u0442 \u043E\u0434\u0438\u043D \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A, \u0437\u0430\u0442\u0435\u043C \u043E\u0442\u0431\u0438\u0432\u0430\u0435\u0442 \u0432\u0430\u0448 \u043F\u0430\u0440\u0442\u043D\u0451\u0440, \u043F\u043E\u0441\u043B\u0435 \u043D\u0435\u0433\u043E \u2014 \u0432\u0442\u043E\u0440\u043E\u0439 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A, \u0430 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u043C\u044F\u0447 \u0441\u043D\u043E\u0432\u0430 \u0432\u0430\u0448. \u0422\u0430\u043A\u043E\u0439 \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442\u0441\u044F \u0434\u043E \u043A\u043E\u043D\u0446\u0430 \u0440\u043E\u0437\u044B\u0433\u0440\u044B\u0448\u0430. \u041E\u0442\u0431\u0438\u0442\u044C \u0437\u0430 \u043F\u0430\u0440\u0442\u043D\u0451\u0440\u0430 \u043D\u0435\u043B\u044C\u0437\u044F, \u0434\u0430\u0436\u0435 \u0435\u0441\u043B\u0438 \u0432\u0430\u0448\u0430 \u0440\u0430\u043A\u0435\u0442\u043A\u0430 \u0431\u043B\u0438\u0436\u0435 \u043A \u043C\u044F\u0447\u0443.",
              "\u041A\u0430\u043A\u0430\u044F \u043A\u043E\u043C\u0430\u043D\u0434\u0430 \u043F\u043E\u0434\u0430\u0451\u0442 \u043F\u0435\u0440\u0432\u043E\u0439, \u0440\u0435\u0448\u0430\u0435\u0442 \u0436\u0440\u0435\u0431\u0438\u0439. \u041A\u0430\u0436\u0434\u044B\u0435 \u0434\u0432\u0430 \u043E\u0447\u043A\u0430 \u043C\u0435\u043D\u044F\u044E\u0442\u0441\u044F \u043F\u043E\u0434\u0430\u044E\u0449\u0438\u0439 \u0438 \u043F\u0440\u0438\u043D\u0438\u043C\u0430\u044E\u0449\u0438\u0439. \u0418\u0433\u0440\u0430 \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u0435\u0442, \u043A\u0442\u043E \u043A\u043E\u043C\u0443 \u043F\u043E\u0434\u0430\u0451\u0442; \u043A\u043B\u0430\u0432\u0438\u0448\u0430 T \u043F\u043E\u0432\u0442\u043E\u0440\u044F\u0435\u0442 \u044D\u0442\u0443 \u0438\u043D\u0444\u043E\u0440\u043C\u0430\u0446\u0438\u044E. \u041D\u0430\u0436\u043C\u0438\u0442\u0435 S, \u0447\u0442\u043E\u0431\u044B \u0443\u0437\u043D\u0430\u0442\u044C \u0441\u043E\u0441\u0442\u0430\u0432\u044B \u043A\u043E\u043C\u0430\u043D\u0434 \u0438 \u0441\u0447\u0451\u0442.",
              "\u0420\u0430\u043A\u0435\u0442\u043A\u0438 \u043F\u0430\u0440\u0442\u043D\u0451\u0440\u043E\u0432 \u0434\u0432\u0438\u0436\u0443\u0442\u0441\u044F \u0441 \u0440\u0430\u0437\u043D\u044B\u043C\u0438 \u0437\u0432\u0443\u043A\u0430\u043C\u0438, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0438\u0445 \u043C\u043E\u0436\u043D\u043E \u0440\u0430\u0437\u043B\u0438\u0447\u0430\u0442\u044C \u043D\u0430 \u0441\u043B\u0443\u0445. \u0423 \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430 \u043A\u0430\u0436\u0434\u043E\u0439 \u043A\u043E\u043C\u0430\u043D\u0434\u044B \u0437\u0432\u0443\u043A \u043F\u043E\u0434\u0430\u0447\u0438 \u0438 \u0443\u0434\u0430\u0440\u0430 \u0442\u0430\u043A\u0436\u0435 \u043D\u0438\u0436\u0435, \u0447\u0435\u043C \u0443 \u0432\u0442\u043E\u0440\u043E\u0433\u043E."),
            rule_section(:arcade, "\u0420\u0435\u0436\u0438\u043C Arcade",
              "\u041E\u0431\u044B\u0447\u043D\u044B\u0439 \u0440\u0435\u0436\u0438\u043C \u043D\u0430\u0437\u044B\u0432\u0430\u0435\u0442\u0441\u044F Classic. \u0414\u043E \u043C\u0430\u0442\u0447\u0430 \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0441\u0442\u043E\u043B\u0430 \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C Arcade. \u0412 \u043D\u0451\u043C \u043A\u0430\u0436\u0434\u044B\u0439 \u0443\u0434\u0430\u0440 \u0440\u0430\u043A\u0435\u0442\u043A\u043E\u0439 \u043D\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043C\u043E \u0434\u0430\u0451\u0442 7% \u0432\u0435\u0440\u043E\u044F\u0442\u043D\u043E\u0441\u0442\u0438 \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u044C \u0449\u0438\u0442 \u0438 7% \u0432\u0435\u0440\u043E\u044F\u0442\u043D\u043E\u0441\u0442\u0438 \u0441\u0434\u0435\u043B\u0430\u0442\u044C \u043C\u044F\u0447 \u043D\u0435\u0432\u0438\u0434\u0438\u043C\u044B\u043C. \u0418\u043D\u043E\u0433\u0434\u0430 \u0441\u0440\u0430\u0431\u0430\u0442\u044B\u0432\u0430\u044E\u0442 \u043E\u0431\u0430 \u044D\u0444\u0444\u0435\u043A\u0442\u0430 \u0441\u0440\u0430\u0437\u0443. \u041D\u0430 \u043F\u043E\u0434\u0430\u0447\u0430\u0445 \u044D\u0444\u0444\u0435\u043A\u0442\u044B \u043D\u0435 \u043F\u043E\u044F\u0432\u043B\u044F\u044E\u0442\u0441\u044F.",
              "- \u0429\u0438\u0442 \u043D\u0430 \u0434\u0435\u0441\u044F\u0442\u044C \u0441\u0435\u043A\u0443\u043D\u0434 \u0438\u0433\u0440\u043E\u0432\u043E\u0433\u043E \u0432\u0440\u0435\u043C\u0435\u043D\u0438 \u0437\u0430\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0432\u0441\u044E \u0432\u0430\u0448\u0443 \u0441\u0442\u043E\u0440\u043E\u043D\u0443. \u0415\u0441\u043B\u0438 \u0432\u044B \u043F\u0440\u043E\u043F\u0443\u0441\u0442\u0438\u0442\u0435 \u043C\u044F\u0447, \u043E\u043D \u043E\u0442\u0440\u0430\u0437\u0438\u0442 \u0435\u0433\u043E \u043F\u0440\u044F\u043C\u043E \u0438 \u043E\u0441\u0442\u0430\u043D\u0435\u0442\u0441\u044F \u0430\u043A\u0442\u0438\u0432\u043D\u044B\u043C. \u041D\u043E\u0432\u044B\u0439 \u0449\u0438\u0442 \u043E\u0431\u043D\u043E\u0432\u043B\u044F\u0435\u0442 \u0432\u0440\u0435\u043C\u044F \u0437\u0430\u0449\u0438\u0442\u044B. \u0412 \u043F\u0430\u0440\u043D\u043E\u043C \u043C\u0430\u0442\u0447\u0435 \u0449\u0438\u0442 \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u043E\u0431\u043E\u0438\u0445 \u043F\u0430\u0440\u0442\u043D\u0451\u0440\u043E\u0432. \u041F\u043E\u043A\u0430 \u0432\u0441\u0435 \u0436\u0434\u0443\u0442 \u043F\u043E\u0434\u0430\u0447\u0438, \u0432\u0440\u0435\u043C\u044F \u043D\u0435 \u0440\u0430\u0441\u0445\u043E\u0434\u0443\u0435\u0442\u0441\u044F; \u043E\u0441\u0442\u0430\u0442\u043E\u043A \u0437\u0430\u0449\u0438\u0442\u044B \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442\u0441\u044F \u0438 \u0432 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u043C \u0440\u043E\u0437\u044B\u0433\u0440\u044B\u0448\u0435.",
              "- \u041D\u0435\u0432\u0438\u0434\u0438\u043C\u044B\u0439 \u043C\u044F\u0447 \u043D\u0435 \u0441\u043B\u044B\u0448\u0435\u043D. \u041F\u0440\u0438\u0434\u0451\u0442\u0441\u044F \u043F\u0440\u0435\u0434\u0443\u0433\u0430\u0434\u0430\u0442\u044C \u0435\u0433\u043E \u043F\u0443\u0442\u044C \u0438 \u043F\u043E\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u0440\u0430\u043A\u0435\u0442\u043A\u0443 \u043D\u0430 \u043D\u0443\u0436\u043D\u043E\u0435 \u043C\u0435\u0441\u0442\u043E. \u041F\u043E\u0441\u043B\u0435 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0433\u043E \u0443\u0434\u0430\u0440\u0430 \u0440\u0430\u043A\u0435\u0442\u043A\u043E\u0439 \u0437\u0432\u0443\u043A \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044F, \u0430 \u043E\u0442\u0441\u043A\u043E\u043A \u043E\u0442 \u0449\u0438\u0442\u0430 \u0435\u0433\u043E \u043D\u0435 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442. \u0421 \u043E\u043A\u043E\u043D\u0447\u0430\u043D\u0438\u0435\u043C \u0440\u043E\u0437\u044B\u0433\u0440\u044B\u0448\u0430 \u043D\u0435\u0432\u0438\u0434\u0438\u043C\u043E\u0441\u0442\u044C \u0442\u043E\u0436\u0435 \u0438\u0441\u0447\u0435\u0437\u0430\u0435\u0442.",
              "\u041A\u043B\u0430\u0432\u0438\u0448\u0430 E \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442, \u043A\u0430\u043A\u0438\u0435 \u044D\u0444\u0444\u0435\u043A\u0442\u044B \u0441\u0435\u0439\u0447\u0430\u0441 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0442."),
            rule_section(:options, "\u0421\u043A\u043E\u0440\u043E\u0441\u0442\u044C \u0438\u0433\u0440\u044B \u0438 \u0446\u0435\u043B\u044C \u043F\u043E \u043E\u0447\u043A\u0430\u043C",
              "\u0421\u043B\u043E\u0436\u043D\u043E\u0441\u0442\u044C \u0437\u0430\u0434\u0430\u0451\u0442\u0441\u044F \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0441\u0442\u043E\u043B\u0430 \u043F\u0435\u0440\u0435\u0434 \u043C\u0430\u0442\u0447\u0435\u043C. \u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0432\u044B\u0431\u0440\u0430\u043D \u043D\u043E\u0440\u043C\u0430\u043B\u044C\u043D\u044B\u0439 \u0443\u0440\u043E\u0432\u0435\u043D\u044C. \u041D\u0430 \u043B\u0451\u0433\u043A\u043E\u043C \u043C\u044F\u0447 \u043C\u0435\u0434\u043B\u0435\u043D\u043D\u0435\u0435, \u043D\u0430 \u0431\u043E\u043B\u0435\u0435 \u0441\u043B\u043E\u0436\u043D\u044B\u0445 \u2014 \u0431\u044B\u0441\u0442\u0440\u0435\u0435. \u0421 \u043F\u043E\u0432\u044B\u0448\u0435\u043D\u0438\u0435\u043C \u0441\u043B\u043E\u0436\u043D\u043E\u0441\u0442\u0438 \u043B\u0443\u0447\u0448\u0435 \u0438\u0433\u0440\u0430\u0435\u0442 \u0438 \u0431\u043E\u0442.",
              "\u0417\u0434\u0435\u0441\u044C \u0436\u0435 \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u043C\u0430\u0442\u0447 \u0434\u043E 7 \u0438\u043B\u0438 21 \u043E\u0447\u043A\u0430 \u0432\u043C\u0435\u0441\u0442\u043E 11. \u0412\u0430\u0440\u0438\u0430\u043D\u0442 \u0441 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u043C \u0447\u0438\u0441\u043B\u043E\u043C \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u0435\u0442 \u0437\u0430\u0434\u0430\u0442\u044C \u0434\u0440\u0443\u0433\u0443\u044E \u0446\u0435\u043B\u044C. \u041F\u0440\u0435\u0438\u043C\u0443\u0449\u0435\u0441\u0442\u0432\u043E \u0432 \u0434\u0432\u0430 \u043E\u0447\u043A\u0430 \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044F \u0432 \u043B\u044E\u0431\u043E\u043C \u0441\u043B\u0443\u0447\u0430\u0435.",
              "\u0412 \u0431\u0435\u0441\u043A\u043E\u043D\u0435\u0447\u043D\u043E\u043C \u0440\u0435\u0436\u0438\u043C\u0435 \u043E\u0447\u043A\u0438 \u0441\u0447\u0438\u0442\u0430\u044E\u0442\u0441\u044F, \u043D\u043E \u0441\u0430\u043C\u0438 \u043F\u043E \u0441\u0435\u0431\u0435 \u043D\u0435 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u044E\u0442 \u043C\u0430\u0442\u0447. \u0417\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u044C \u0435\u0433\u043E \u043C\u043E\u0436\u0435\u0442 \u0445\u043E\u0437\u044F\u0438\u043D \u0441\u0442\u043E\u043B\u0430 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0435\u043C Ctrl+Q."),
            rule_section(:personal, "\u041C\u044B\u0448\u044C, \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0435 \u0443\u0434\u0430\u0440\u044B \u0438 \u0437\u0432\u0443\u043A",
              "\u041D\u0430 \u0438\u0433\u0440\u043E\u0432\u043E\u043C \u043F\u043E\u043B\u0435 \u043C\u043E\u0436\u043D\u043E \u0441\u0440\u0430\u0437\u0443 \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C\u0441\u044F \u043C\u044B\u0448\u044C\u044E \u0438\u043B\u0438 \u0441\u0435\u043D\u0441\u043E\u0440\u043D\u043E\u0439 \u043F\u0430\u043D\u0435\u043B\u044C\u044E: \u0434\u0432\u0438\u0433\u0430\u0439\u0442\u0435 \u0443\u043A\u0430\u0437\u0430\u0442\u0435\u043B\u044C \u0432\u043B\u0435\u0432\u043E \u0438 \u0432\u043F\u0440\u0430\u0432\u043E, \u0430 \u043B\u0435\u0432\u043E\u0439 \u043A\u043D\u043E\u043F\u043A\u043E\u0439 \u043F\u043E\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u0438 \u043E\u0442\u0431\u0438\u0432\u0430\u0439\u0442\u0435 \u043C\u044F\u0447.",
              "\u0421\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0435 Ctrl+P \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0432\u0430\u0448\u0438 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0438\u0433\u0440\u044B:",
              "- \u0410\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u043E\u0435 \u043E\u0442\u0431\u0438\u0432\u0430\u043D\u0438\u0435 \u0437\u0430\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u0442 \u0440\u0430\u043A\u0435\u0442\u043A\u0443 \u0441\u0430\u043C\u043E\u0441\u0442\u043E\u044F\u0442\u0435\u043B\u044C\u043D\u043E \u0443\u0434\u0430\u0440\u044F\u0442\u044C \u043F\u043E \u043C\u044F\u0447\u0443 \u0432 \u043F\u0440\u0435\u0434\u0435\u043B\u0430\u0445 \u0434\u043E\u0441\u044F\u0433\u0430\u0435\u043C\u043E\u0441\u0442\u0438. \u0414\u0432\u0438\u0433\u0430\u0442\u044C \u0435\u0451 \u0438 \u043F\u043E\u0434\u0430\u0432\u0430\u0442\u044C \u0432\u0441\u0451 \u0440\u0430\u0432\u043D\u043E \u043D\u0443\u0436\u043D\u043E \u0432\u0430\u043C. \u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u044D\u0442\u0430 \u043F\u043E\u043C\u043E\u0449\u044C \u0432\u044B\u043A\u043B\u044E\u0447\u0435\u043D\u0430.",
              "- \u0413\u0440\u043E\u043C\u043A\u043E\u0441\u0442\u044C \u0441\u0432\u043E\u0435\u0439 \u0440\u0430\u043A\u0435\u0442\u043A\u0438 \u043C\u0435\u043D\u044F\u0435\u0442 \u0433\u0440\u043E\u043C\u043A\u043E\u0441\u0442\u044C \u0437\u0432\u0443\u043A\u0430 \u0435\u0451 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u044F.",
              "- \u0413\u0440\u043E\u043C\u043A\u043E\u0441\u0442\u044C \u0440\u0430\u043A\u0435\u0442\u043A\u0438 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u043C\u0435\u043D\u044F\u0435\u0442 \u0433\u0440\u043E\u043C\u043A\u043E\u0441\u0442\u044C \u0435\u0433\u043E \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u044F.",
              "- \u0413\u0440\u043E\u043C\u043A\u043E\u0441\u0442\u044C \u0434\u0438\u043A\u0442\u043E\u0440\u0430 \u043E\u0442\u043D\u043E\u0441\u0438\u0442\u0441\u044F \u043A \u0433\u043E\u043B\u043E\u0441\u043E\u0432\u044B\u043C \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u044F\u043C \u0438\u0433\u0440\u044B.",
              "\u041A\u0440\u043E\u043C\u0435 \u0442\u043E\u0433\u043E, Shift+E \u043F\u0435\u0440\u0435\u043A\u043B\u044E\u0447\u0430\u0435\u0442 \u0437\u0432\u0443\u043A\u043E\u0432\u044B\u0435 \u043E\u0440\u0438\u0435\u043D\u0442\u0438\u0440\u044B \u0443 \u0431\u043E\u043A\u043E\u0432\u044B\u0445 \u0431\u043E\u0440\u0442\u043E\u0432: \u0448\u0443\u043C, \u0442\u043E\u043D\u044B \u0438\u043B\u0438 \u0442\u0438\u0448\u0438\u043D\u0430. \u0427\u0435\u043C \u0431\u043B\u0438\u0436\u0435 \u0440\u0430\u043A\u0435\u0442\u043A\u0430 \u043A \u0431\u043E\u0440\u0442\u0443, \u0442\u0435\u043C \u0433\u0440\u043E\u043C\u0447\u0435 \u0435\u0433\u043E \u0441\u0438\u0433\u043D\u0430\u043B."),
            rule_section(:credits, "\u0418\u0441\u0442\u043E\u0440\u0438\u044F \u0438\u0433\u0440\u044B",
              "Axel Pong \u043D\u0435 \u0431\u044B\u043B \u043F\u0440\u0438\u0434\u0443\u043C\u0430\u043D \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u0435\u043C papierek. \u0418\u0437\u043D\u0430\u0447\u0430\u043B\u044C\u043D\u043E \u0438\u0433\u0440\u0430 \u043D\u0430\u0437\u044B\u0432\u0430\u043B\u0430\u0441\u044C Dragon-Pong, \u0437\u0430\u0442\u0435\u043C \u0435\u0451 \u0434\u043E\u0440\u0430\u0431\u043E\u0442\u0430\u043B\u0438 Axel \u0438 balteam. \u0412 ELTEN \u043E\u043D\u0430 \u043F\u0435\u0440\u0435\u043D\u0435\u0441\u0435\u043D\u0430 \u0441 \u0438\u0445 \u0441\u043E\u0433\u043B\u0430\u0441\u0438\u044F."),
            rule_section(:controls, "\u041A\u043B\u0430\u0432\u0438\u0448\u0438 \u0443\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F",
              "\u0421\u0442\u0440\u0435\u043B\u043A\u0430 \u0432\u043B\u0435\u0432\u043E: \u043F\u0435\u0440\u0435\u0434\u0432\u0438\u043D\u0443\u0442\u044C \u0440\u0430\u043A\u0435\u0442\u043A\u0443 \u0432\u043B\u0435\u0432\u043E.",
              "\u0421\u0442\u0440\u0435\u043B\u043A\u0430 \u0432\u043F\u0440\u0430\u0432\u043E: \u043F\u0435\u0440\u0435\u0434\u0432\u0438\u043D\u0443\u0442\u044C \u0440\u0430\u043A\u0435\u0442\u043A\u0443 \u0432\u043F\u0440\u0430\u0432\u043E.",
              "\u0421\u0442\u0440\u0435\u043B\u043A\u0430 \u0432\u0432\u0435\u0440\u0445: \u043F\u043E\u0434\u0430\u0442\u044C \u0438\u043B\u0438 \u043E\u0442\u0431\u0438\u0442\u044C \u043C\u044F\u0447.",
              "\u041F\u0440\u043E\u0431\u0435\u043B: \u043F\u043E\u0434\u0430\u0442\u044C \u0438\u043B\u0438 \u043E\u0442\u0431\u0438\u0442\u044C \u043C\u044F\u0447.",
              "\u041B\u0435\u0432\u0430\u044F \u043A\u043D\u043E\u043F\u043A\u0430 \u043C\u044B\u0448\u0438: \u043F\u043E\u0434\u0430\u0442\u044C \u0438\u043B\u0438 \u043E\u0442\u0431\u0438\u0442\u044C \u043C\u044F\u0447.",
              "C: \u0443\u0437\u043D\u0430\u0442\u044C \u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u0441\u0432\u043E\u0435\u0439 \u0440\u0430\u043A\u0435\u0442\u043A\u0438 \u0438\u043B\u0438 \u0440\u0430\u043A\u0435\u0442\u043A\u0438 \u0438\u0433\u0440\u043E\u043A\u0430, \u0437\u0430 \u043A\u043E\u0442\u043E\u0440\u044B\u043C \u0432\u044B \u043D\u0430\u0431\u043B\u044E\u0434\u0430\u0435\u0442\u0435.",
              "S: \u0443\u0437\u043D\u0430\u0442\u044C \u0441\u0447\u0451\u0442; \u0432 \u043F\u0430\u0440\u043D\u043E\u043C \u043C\u0430\u0442\u0447\u0435 \u0442\u0430\u043A\u0436\u0435 \u0441\u043E\u0441\u0442\u0430\u0432\u044B \u043A\u043E\u043C\u0430\u043D\u0434.",
              "T: \u0443\u0437\u043D\u0430\u0442\u044C \u043F\u043E\u0434\u0430\u044E\u0449\u0435\u0433\u043E \u0438 \u0441\u043E\u0441\u0442\u043E\u044F\u043D\u0438\u0435 \u0441\u043E\u0435\u0434\u0438\u043D\u0435\u043D\u0438\u044F; \u0432 \u043F\u0430\u0440\u043D\u043E\u043C \u043C\u0430\u0442\u0447\u0435 \u0442\u0430\u043A\u0436\u0435 \u043F\u0440\u0438\u043D\u0438\u043C\u0430\u044E\u0449\u0435\u0433\u043E.",
              "Ctrl+W: \u043F\u043E\u0442\u043E\u0440\u043E\u043F\u0438\u0442\u044C \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u0441 \u043F\u043E\u0434\u0430\u0447\u0435\u0439.",
              "E: \u0443\u0437\u043D\u0430\u0442\u044C \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0435 \u044D\u0444\u0444\u0435\u043A\u0442\u044B Arcade.",
              "Shift+E: \u043F\u0435\u0440\u0435\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u0437\u0432\u0443\u043A\u0438 \u0431\u043E\u043A\u043E\u0432\u044B\u0445 \u0431\u043E\u0440\u0442\u043E\u0432.",
              "Ctrl+P: \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0438\u0433\u0440\u044B.",
              "1: \u043D\u0430\u0431\u043B\u044E\u0434\u0430\u0442\u044C \u0441\u043E \u0441\u0442\u043E\u0440\u043E\u043D\u044B \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430.",
              "2: \u043D\u0430\u0431\u043B\u044E\u0434\u0430\u0442\u044C \u0441\u043E \u0441\u0442\u043E\u0440\u043E\u043D\u044B \u0432\u0442\u043E\u0440\u043E\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430.",
              "3: \u0432 \u043F\u0430\u0440\u043D\u043E\u043C \u043C\u0430\u0442\u0447\u0435 \u043D\u0430\u0431\u043B\u044E\u0434\u0430\u0442\u044C \u0441\u043E \u0441\u0442\u043E\u0440\u043E\u043D\u044B \u0442\u0440\u0435\u0442\u044C\u0435\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430.",
              "4: \u0432 \u043F\u0430\u0440\u043D\u043E\u043C \u043C\u0430\u0442\u0447\u0435 \u043D\u0430\u0431\u043B\u044E\u0434\u0430\u0442\u044C \u0441\u043E \u0441\u0442\u043E\u0440\u043E\u043D\u044B \u0447\u0435\u0442\u0432\u0451\u0440\u0442\u043E\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430.")
          ]
        end
      end
